img = [[0, 0], [255, 255]]

def histogram(img, bins=2):
    step = 256 / bins
    counts = [0] * bins
    for row in img:
        for v in row:
            counts[min(int(v / step), bins - 1)] += 1
    return counts

print(histogram(img))

scene = [
    [0, 0, 0, 0, 0],
    [0, 9, 9, 0, 0],
    [0, 9, 9, 0, 0],
    [0, 0, 0, 0, 0],
]
template = [
    [9, 9],
    [9, 9],
]

def find(scene, tpl):
    th, tw = len(tpl), len(tpl[0])
    best, best_pos = None, None
    for y in range(len(scene) - th + 1):
        for x in range(len(scene[0]) - tw + 1):
            diff = sum(abs(scene[y + dy][x + dx] - tpl[dy][dx])
                       for dy in range(th) for dx in range(tw))
            if best is None or diff < best:
                best, best_pos = diff, (y, x)
    return best_pos, best

pos, diff = find(scene, template)
print("нашли в позиции (строка, столбец):", pos)
print("расхождение:", diff, "— ноль значит точное совпадение")
